/**
 * bind — inject handlers (boundary injection; catalog name → implementation) and get one
 * callable per component. Handler resolution happens HERE, once; each callable runs the
 * static straight-line function for that component through the resolved references — NOT
 * the runBehavior tree-walk. Observationally equivalent to the runBehavior path:
 * same values, same emitted op sequence, same Failure code/message.
 */
export function bind(handlers: Handlers): Record<string, (input?: Scope) => Value> {
  return {
    "findAll": bind_findAll(handlers),
    "filterPaginateSort": bind_filterPaginateSort(handlers),
    "findFirst": bind_findFirst(handlers),
    "findUnique": bind_findUnique(handlers),
    "nestedFindAll": bind_nestedFindAll(handlers),
    "nestedFindFirst": bind_nestedFindFirst(handlers),
    "nestedFindUnique": bind_nestedFindUnique(handlers),
    "nestedRelations": bind_nestedRelations(handlers),
    "compositeRelations": bind_compositeRelations(handlers),
    "create": bind_create(handlers),
    "update": bind_update(handlers),
    "upsert": bind_upsert(handlers),
    "createMany": bind_createMany(handlers),
    "upsertMany": bind_upsertMany(handlers),
    "updateMany": bind_updateMany(handlers),
    "nestedCreate": bind_nestedCreate(handlers),
    "nestedUpsert": bind_nestedUpsert(handlers),
    "nestedUpdate": bind_nestedUpdate(handlers),
    "delete": bind_delete(handlers),
  };
}

/**
 * bindAsync — as bind, but async handlers are awaited. Components with a real-concurrency
 * plan drive the runPlanAsync bounded-parallel primitive (same in-flight behavior as the
 * async ir path); strictly-sequential components run as awaited straight statements.
 */
export function bindAsync(handlers: AsyncHandlers): Record<string, (input?: Scope) => Promise<Value>> {
  return {
    "findAll": bindAsync_findAll(handlers),
    "filterPaginateSort": bindAsync_filterPaginateSort(handlers),
    "findFirst": bindAsync_findFirst(handlers),
    "findUnique": bindAsync_findUnique(handlers),
    "nestedFindAll": bindAsync_nestedFindAll(handlers),
    "nestedFindFirst": bindAsync_nestedFindFirst(handlers),
    "nestedFindUnique": bindAsync_nestedFindUnique(handlers),
    "nestedRelations": bindAsync_nestedRelations(handlers),
    "compositeRelations": bindAsync_compositeRelations(handlers),
    "create": bindAsync_create(handlers),
    "update": bindAsync_update(handlers),
    "upsert": bindAsync_upsert(handlers),
    "createMany": bindAsync_createMany(handlers),
    "upsertMany": bindAsync_upsertMany(handlers),
    "updateMany": bindAsync_updateMany(handlers),
    "nestedCreate": bindAsync_nestedCreate(handlers),
    "nestedUpsert": bindAsync_nestedUpsert(handlers),
    "nestedUpdate": bindAsync_nestedUpdate(handlers),
    "delete": bindAsync_delete(handlers),
  };
}


