/**
 * bindTyped — inject handlers and get one TYPED callable per covered component. Runs the same
 * interpreter-free straight-line runner as bind() (boundary injection; no per-node dispatch, no
 * IR-walk), then materializes the component result into its declared outputType. The materialization
 * is tsc-checked; under TS erasure it is runtime-equivalent to bind() (same value, retyped).
 */
export function bindTyped(handlers: Handlers): BindTyped {
  const __runners = bind(handlers);
  return {
    "findAll": (input?: Scope): UserRow[] => marshalOutput_findAll(__runners["findAll"](input)),
    "filterPaginateSort": (input?: Scope): PostFullRow[] => marshalOutput_filterPaginateSort(__runners["filterPaginateSort"](input)),
    "findFirst": (input?: Scope): UserRow[] => marshalOutput_findFirst(__runners["findFirst"](input)),
    "findUnique": (input?: Scope): UserRow[] => marshalOutput_findUnique(__runners["findUnique"](input)),
    "nestedFindAll": (input?: Scope): UserWithPosts[] => marshalOutput_nestedFindAll(__runners["nestedFindAll"](input)),
    "nestedFindFirst": (input?: Scope): UserWithPosts[] => marshalOutput_nestedFindFirst(__runners["nestedFindFirst"](input)),
    "nestedFindUnique": (input?: Scope): UserWithPosts[] => marshalOutput_nestedFindUnique(__runners["nestedFindUnique"](input)),
    "nestedRelations": (input?: Scope): UserWithPostsAndComments[] => marshalOutput_nestedRelations(__runners["nestedRelations"](input)),
    "compositeRelations": (input?: Scope): TenantUserWithPosts[] => marshalOutput_compositeRelations(__runners["compositeRelations"](input)),
    "create": (input?: Scope): WriteSummary[] => marshalOutput_create(__runners["create"](input)),
    "update": (input?: Scope): WriteSummary[] => marshalOutput_update(__runners["update"](input)),
    "upsert": (input?: Scope): IdRow[] => marshalOutput_upsert(__runners["upsert"](input)),
    "createMany": (input?: Scope): WriteSummary[] => marshalOutput_createMany(__runners["createMany"](input)),
    "upsertMany": (input?: Scope): WriteSummary[] => marshalOutput_upsertMany(__runners["upsertMany"](input)),
    "updateMany": (input?: Scope): WriteSummary[] => marshalOutput_updateMany(__runners["updateMany"](input)),
    "nestedCreate": (input?: Scope): WriteSummary[][] => marshalOutput_nestedCreate(__runners["nestedCreate"](input)),
    "nestedUpsert": (input?: Scope): WriteSummary[][] => marshalOutput_nestedUpsert(__runners["nestedUpsert"](input)),
    "nestedUpdate": (input?: Scope): WriteSummary[][] => marshalOutput_nestedUpdate(__runners["nestedUpdate"](input)),
    "delete": (input?: Scope): WriteSummary[][] => marshalOutput_delete(__runners["delete"](input)),
  };
}

